using System;using System.Collections.Generic;using System.Linq;using System.Text.RegularExpressions;using System.IO;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;
namespace Shiri {
 [DataContract] public class OcrLine{[DataMember]public string Text;[DataMember]public double Left,Top,Right,Bottom;public double X{get{return (Left+Right)/2;}}public double Y{get{return (Top+Bottom)/2;}}}
 [DataContract] public class OcrLayout{[DataMember]public int Width,Height;[DataMember]public List<OcrLine> Lines;public static OcrLayout Parse(string json){using(var stream=new MemoryStream(System.Text.Encoding.UTF8.GetBytes(json)))return (OcrLayout)new DataContractJsonSerializer(typeof(OcrLayout)).ReadObject(stream);}}
 [DataContract] public sealed class OcrCandidate{[DataMember]public Course Value;[DataMember]public bool Include=true;[DataMember]public double Left,Top,Right,Bottom;}
 public static class CourseRecognition {
 sealed class Header{public int Day;public double X,Bottom;}
 static bool Colored(System.Drawing.Color c){return Math.Min(c.R,Math.Min(c.G,c.B))>125&&Math.Max(c.R,Math.Max(c.G,c.B))-Math.Min(c.R,Math.Min(c.G,c.B))>7;}
 public static List<OcrCandidate> Parse(OcrLayout document,string imagePath){foreach(var line in document.Lines)line.Text=Regex.Replace(line.Text??"",@"\s+","");var headers=new List<Header>();foreach(var line in document.Lines)foreach(Match m in Regex.Matches(line.Text,@"(?:星期|周)([一二三四五六日天])")){int day="一二三四五六日".IndexOf(m.Groups[1].Value)+1;if(m.Groups[1].Value=="天")day=7;headers.Add(new Header{Day=day,X=line.Left+(m.Index+m.Length/2.0)/Math.Max(1,line.Text.Length)*(line.Right-line.Left),Bottom=line.Bottom});}headers=headers.OrderBy(h=>h.X).ToList();var output=new List<OcrCandidate>();if(headers.Count<2){foreach(var group in Groups(document.Lines.Where(l=>!Regex.IsMatch(l.Text,@"(?:星期|周)[一二三四五六日天]")).ToList()))output.Add(Candidate(group,0,0,0,document.Width,document.Height));return output;}
 var pitches=new List<double>();for(int n=1;n<headers.Count;n++)if(headers[n].Day>headers[n-1].Day)pitches.Add((headers[n].X-headers[n-1].X)/(headers[n].Day-headers[n-1].Day));if(pitches.Count==0)return output;pitches.Sort();double pitch=pitches[pitches.Count/2],top=headers.Max(h=>h.Bottom);var origin=headers[0];using(var bitmap=new System.Drawing.Bitmap(imagePath)){int min=headers.Min(h=>h.Day),max=headers.Max(h=>h.Day);foreach(var line in document.Lines.Where(l=>l.Y>top)){int inferred=origin.Day+(int)Math.Round((line.X-origin.X)/pitch);if(inferred>=1&&inferred<=7){min=Math.Min(min,inferred);max=Math.Max(max,inferred);}}for(int d=min;d<=max;d++){double center=origin.X+(d-origin.Day)*pitch,left=Math.Max(0,center-pitch/2+2),right=Math.Min(document.Width-1,center+pitch/2-2);var column=document.Lines.Where(l=>l.Y>top&&l.X>=left&&l.X<=right&&!Regex.IsMatch(l.Text,@"(?:星期|周)[一二三四五六日天]")).ToList();var cells=new List<Tuple<int,int>>();int start=-1,holes=0;for(int y=(int)top+3;y<document.Height;y++){int votes=0;foreach(double fraction in new[]{.12,.5,.88}){int x=Math.Min(bitmap.Width-1,Math.Max(0,(int)(left+(right-left)*fraction)));if(Colored(bitmap.GetPixel(x,Math.Min(bitmap.Height-1,y))))votes++;}if(votes>=2){if(start<0)start=y;holes=0;}else if(start>=0){holes++;if(holes>3){if(y-start-holes>=12)cells.Add(Tuple.Create(start,y-holes+1));start=-1;holes=0;}}}if(start>=0)cells.Add(Tuple.Create(start,document.Height));foreach(var cell in cells){var inside=column.Where(l=>l.Y>=cell.Item1&&l.Y<=cell.Item2).ToList();if(inside.Count==0)continue;var candidate=Candidate(inside,d,left,cell.Item1,right,cell.Item2);if(candidate.Value.Title.Length>0||candidate.Value.Start.Length>0)output.Add(candidate);column.RemoveAll(l=>inside.Contains(l));}foreach(var group in Groups(column)){var candidate=Candidate(group,d,left,group.Min(l=>l.Top),right,group.Max(l=>l.Bottom));if(candidate.Value.Title.Length>0)output.Add(candidate);}}}return output;
 }
 static List<List<OcrLine>> Groups(List<OcrLine> lines){var groups=new List<List<OcrLine>>();var current=new List<OcrLine>();OcrLine previous=null;foreach(var line in lines.OrderBy(l=>l.Top)){if(previous!=null&&line.Top-previous.Bottom>Math.Max(12,(previous.Bottom-previous.Top)*1.3)){groups.Add(current);current=new List<OcrLine>();}current.Add(line);previous=line;}if(current.Count>0)groups.Add(current);return groups;}
 static OcrCandidate Candidate(List<OcrLine> lines,int day,double left,double top,double right,double bottom){lines=lines.OrderBy(l=>l.Top).ToList();string joined=String.Join("",lines.Select(l=>l.Text));var times=Regex.Matches(joined,@"([0-2]?\d)[:：]([0-5]\d)").Cast<Match>().Select(m=>int.Parse(m.Groups[1].Value).ToString("00")+":"+m.Groups[2].Value).ToList();string title="",place="";foreach(var line in lines){string value=line.Text;if(Regex.IsMatch(value,@"(\d[:：]\d|\d.*周|\d.*节)")||Regex.IsMatch(value,@"^(?:(?:星期|周)[一二三四五六日天]|\d{1,2}月|第?\d{1,2})$"))continue;bool location=Regex.IsMatch(value,@"(教学楼|实验楼|试验楼|博雅楼|教室|体育馆|操场|报告厅|校区|[楼馆室场])")||Regex.IsMatch(value,@"^[A-Za-z]?\d{2,5}$");if(location)place+=value;else title+=value;}
 var c=new Course{Title=title,Location=place,Day=day,Start=times.Count>0?times[0]:"",End=times.Count>1?times[1]:"",FirstWeek=0,LastWeek=0};var weeks=Regex.Match(joined,@"(\d{1,2})[-—–~至一](\d{1,2})周");if(weeks.Success){c.FirstWeek=int.Parse(weeks.Groups[1].Value);c.LastWeek=int.Parse(weeks.Groups[2].Value);}var periods=Regex.Match(joined,@"第?(\d{1,2})[-—–~至](\d{1,2})节");if(periods.Success){c.FirstPeriod=int.Parse(periods.Groups[1].Value);c.LastPeriod=int.Parse(periods.Groups[2].Value);}return new OcrCandidate{Value=c,Left=left,Top=top,Right=right,Bottom=bottom};
 }
 }
}
